  manifest: "/manifest.json",
  appleWebApp: {
    capable: true,
    statusBarStyle: "default",
    title: "AI Tool Navigator",
  },
  openGraph: {
    type: 'website',
    siteName: 'AI Tool Navigator',
    title: "AI Tool Navigator | Best AI Tools Comparison",
    description: "Compare the best AI tools for writing, coding, image generation, and more. Find the perfect AI solution for your workflow.",
  },
  twitter: {
    card: 'summary_large_image',
    title: "AI Tool Navigator | Best AI Tools Comparison",
    description: "Compare the best AI tools for writing, coding, image generation, and more. Find the perfect AI solution for your workflow.",
  },
};

// Client component wrapper for ExitIntentModal
function ExitIntentWrapper() {
  const { variant, isLoading } = useExitIntentABTest();

  if (isLoading) {
    return null;
  }

  return <ExitIntentModal variant={variant} enabled={true} />;
}

export default async function RootLayout({
  children,
  params
}: Readonly<{
  children: React.ReactNode;
  params: Promise<{locale: string}>;
}>) {
  const {locale} = await params;
  const messages = await getMessages();
  const organizationSchema = generateOrganizationSchema();
  const searchBoxSchema = generateSearchBoxSchema(locale);

  return (
    <html lang={locale} suppressHydrationWarning>
      <head>
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(organizationSchema) }}
        />
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(searchBoxSchema) }}
        />
      </head>
      <body
        className={`${geistSans.variable} ${geistMono.variable} antialiased`}
      >
        <NextIntlClientProvider messages={messages}>
          <ThemeProvider
            attribute="class"
            defaultTheme="system"
            enableSystem
            disableTransitionOnChange
          >
            <CompareProvider>
            <GoogleAnalytics gaId={process.env.NEXT_PUBLIC_GA_ID || "G-727KCHJ884"} />
            <StickyNotificationBar />
            <Navigation />
            {children}
            <Footer />
            <CompareBar />
            <NewsletterPopup />
            <ExitIntentWrapper />
            <BackToTop />
            </CompareProvider>
          </ThemeProvider>
        </NextIntlClientProvider>
      </body>
    </html>
  );
}

